import React, { useEffect, useRef, useState, useCallback } from 'react';
import api from '../services/api';

/*
  AdminCharts — Statistiques visuelles EduMatch
  ─────────────────────────────────────────────
  Fix dark mode : lecture des CSS vars via getComputedStyle()
  Fix matières  : réservations réelles par matière des profs
*/

// ── Charger Chart.js ────────────────────────────────────────────
function loadChart() {
  return new Promise(resolve => {
    if (window.Chart) { resolve(window.Chart); return; }
    const s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
    s.onload = () => resolve(window.Chart);
    document.head.appendChild(s);
  });
}

// ── Lire les CSS variables selon le thème actuel ────────────────
function getCssVar(name, fallback = '') {
  return getComputedStyle(document.documentElement)
    .getPropertyValue(name).trim() || fallback;
}

function getThemeColors() {
  return {
    text:    getCssVar('--text',    '#f0f0f8'),
    text2:   getCssVar('--text2',   '#9999bb'),
    surface: getCssVar('--surface', '#12121a'),
    border:  getCssVar('--border',  '#2a2a3a'),
    accent:  getCssVar('--accent',  '#6c63ff'),
  };
}

// ── Palette graphiques ───────────────────────────────────────────
const PAL = [
  '#6c63ff', '#ff6584', '#43e97b', '#38bdf8',
  '#f59e0b', '#a78bfa', '#34d399', '#fb923c',
];

// ── Hook Chart.js ────────────────────────────────────────────────
function useChart(ref, buildFn, deps) {
  const inst = useRef(null);
  useEffect(() => {
    if (!ref.current) return;
    loadChart().then(Chart => {
      if (inst.current) inst.current.destroy();
      const colors = getThemeColors();
      inst.current = new Chart(ref.current.getContext('2d'), buildFn(Chart, colors));
    });
    return () => { if (inst.current) inst.current.destroy(); };
  }, deps); // eslint-disable-line
}

// ════════════════════════════════════════════
//  1. LINE CHART — Réservations par mois
// ════════════════════════════════════════════
function LineReservations({ data }) {
  const ref = useRef(null);
  useChart(ref, (Chart, c) => ({
    type: 'line',
    data: {
      labels: data.map(d => d.mois),
      datasets: [{
        label: 'Réservations',
        data:  data.map(d => d.total),
        borderColor:     '#6c63ff',
        backgroundColor: 'rgba(108,99,255,0.15)',
        borderWidth: 2.5,
        fill: true,
        tension: 0.4,
        pointBackgroundColor: '#6c63ff',
        pointBorderColor:     c.surface,
        pointBorderWidth: 2,
        pointRadius: 5,
        pointHoverRadius: 8,
      }],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: c.surface,
          titleColor: c.text2,
          bodyColor:  c.text,
          borderColor: c.border,
          borderWidth: 1,
          callbacks: {
            label: ctx => ` ${ctx.parsed.y} réservation${ctx.parsed.y > 1 ? 's' : ''}`,
          },
        },
      },
      scales: {
        x: {
          grid:  { color: c.border + '55' },
          ticks: { color: c.text2, font: { size: 11 } },
        },
        y: {
          beginAtZero: true,
          grid:  { color: c.border + '55' },
          ticks: { color: c.text2, font: { size: 11 }, stepSize: 1 },
        },
      },
    },
  }), [JSON.stringify(data)]);
  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════
//  2. BAR CHART — Réservations par matière
// ════════════════════════════════════════════
function BarMatieres({ matieres, metric }) {
  const ref = useRef(null);
  useChart(ref, (Chart, c) => ({
    type: 'bar',
    data: {
      labels: matieres.map(m => m.matiere),
      datasets: [{
        label: metric === 'nb_resa' ? 'Réservations' : 'Formateurs',
        data:  matieres.map(m => m[metric]),
        backgroundColor: matieres.map((_, i) => PAL[i % PAL.length] + 'bb'),
        borderColor:     matieres.map((_, i) => PAL[i % PAL.length]),
        borderWidth: 1.5,
        borderRadius: 6,
      }],
    },
    options: {
      indexAxis: 'y',
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: c.surface,
          titleColor: c.text2,
          bodyColor:  c.text,
          borderColor: c.border,
          borderWidth: 1,
        },
      },
      scales: {
        x: {
          beginAtZero: true,
          grid:  { color: c.border + '55' },
          ticks: { color: c.text2, font: { size: 11 }, stepSize: 1 },
        },
        y: {
          grid:  { display: false },
          ticks: { color: c.text, font: { size: 12, weight: '500' } },
        },
      },
    },
  }), [JSON.stringify(matieres), metric]);
  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════
//  3. DONUT — Mode d'enseignement
// ════════════════════════════════════════════
function DonutModes({ data }) {
  const ref = useRef(null);
  useChart(ref, (Chart, c) => ({
    type: 'doughnut',
    data: {
      labels: data.map(d => d.label),
      datasets: [{
        data:            data.map(d => d.val),
        backgroundColor: ['#6c63ff', '#43e97b'],
        borderColor:     c.surface,
        borderWidth: 3,
        hoverOffset: 8,
      }],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      cutout: '68%',
      plugins: {
        legend: {
          position: 'bottom',
          labels: {
            color: c.text,
            font: { size: 12 },
            padding: 16,
            usePointStyle: true,
            pointStyleWidth: 10,
          },
        },
        tooltip: {
          backgroundColor: c.surface,
          titleColor: c.text2,
          bodyColor:  c.text,
          borderColor: c.border,
          borderWidth: 1,
          callbacks: {
            label: ctx => ` ${ctx.label} : ${ctx.parsed} formateur${ctx.parsed > 1 ? 's' : ''}`,
          },
        },
      },
    },
  }), [JSON.stringify(data)]);
  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════
//  4. DONUT — Statut des professeurs
// ════════════════════════════════════════════
function DonutStatut({ data }) {
  const ref = useRef(null);
  useChart(ref, (Chart, c) => ({
    type: 'doughnut',
    data: {
      labels: data.map(d => d.label),
      datasets: [{
        data:            data.map(d => d.val),
        backgroundColor: ['#43e97b', '#f59e0b', '#ef4444'],
        borderColor:     c.surface,
        borderWidth: 3,
        hoverOffset: 8,
      }],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      cutout: '68%',
      plugins: {
        legend: {
          position: 'bottom',
          labels: {
            color: c.text,
            font: { size: 12 },
            padding: 16,
            usePointStyle: true,
            pointStyleWidth: 10,
          },
        },
        tooltip: {
          backgroundColor: c.surface,
          titleColor: c.text2,
          bodyColor:  c.text,
          borderColor: c.border,
          borderWidth: 1,
          callbacks: {
            label: ctx => ` ${ctx.label} : ${ctx.parsed} profil${ctx.parsed > 1 ? 's' : ''}`,
          },
        },
      },
    },
  }), [JSON.stringify(data)]);
  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════
//  CARTE CONTENEUR
// ════════════════════════════════════════════
function Card({ icon, title, subtitle, height = 240, children, extra }) {
  const isOk   = subtitle?.startsWith('✅');
  const isWarn = subtitle?.startsWith('⚠️');
  return (
    <div style={{
      background: 'var(--surface)',
      border: '1px solid var(--border)',
      borderRadius: 18,
      padding: '20px 22px',
      display: 'flex',
      flexDirection: 'column',
      gap: 12,
    }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 8 }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
            <span style={{ fontSize: '1.05rem' }}>{icon}</span>
            <span style={{ fontFamily: 'Syne,sans-serif', fontWeight: 700, fontSize: '.9rem', color: 'var(--text)' }}>
              {title}
            </span>
          </div>
          {subtitle && (
            <div style={{ fontSize: '.72rem', color: isOk ? '#43e97b' : isWarn ? '#f59e0b' : 'var(--text2)', fontWeight: 500 }}>
              {subtitle}
            </div>
          )}
        </div>
        {extra}
      </div>

      {/* Graphique */}
      <div style={{ height, position: 'relative' }}>
        {children}
      </div>
    </div>
  );
}

function Empty({ msg }) {
  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 8, color: 'var(--text2)', fontSize: '.82rem' }}>
      <span style={{ fontSize: '2rem', opacity: .6 }}>📭</span>
      <span>{msg}</span>
    </div>
  );
}

// ════════════════════════════════════════════
//  COMPOSANT PRINCIPAL
// ════════════════════════════════════════════
export default function AdminCharts({ stats = {} }) {
  const [data, setData]       = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);
  const [domainIdx, setDomainIdx] = useState(0);
  const [metric, setMetric]   = useState('nb_resa'); // nb_resa en priorité

  useEffect(() => {
    api.get('/api/admin/stats/charts')
      .then(res => { setData(res.data); setLoading(false); })
      .catch(err => {
        console.error('[AdminCharts]', err);
        setError('Impossible de charger les statistiques. Vérifiez la console uvicorn.');
        setLoading(false);
      });
  }, []);

  if (loading) return (
    <div style={{ padding: 48, textAlign: 'center', color: 'var(--text2)' }}>
      <div style={{ fontSize: '2rem', marginBottom: 10 }}>📊</div>
      <div style={{ fontSize: '.9rem' }}>Chargement des statistiques…</div>
    </div>
  );

  if (error) return (
    <div style={{ padding: 24, textAlign: 'center', color: '#ef4444', fontSize: '.85rem', background: 'rgba(239,68,68,0.08)', borderRadius: 12, border: '1px solid rgba(239,68,68,0.2)' }}>
      ❌ {error}
    </div>
  );

  const {
    reservations_par_mois = [],
    matieres_par_domaine  = [],
    modes_enseignement    = [],
    statut_profs          = [],
  } = data;

  const totalResa      = reservations_par_mois.reduce((a, b) => a + b.total, 0);
  const domaineActif   = matieres_par_domaine[domainIdx] || null;
  const modesFiltered  = modes_enseignement.filter(m => m.val > 0);
  const statutFiltered = statut_profs.filter(s => s.val > 0);
  const totalStatut    = statutFiltered.reduce((a, b) => a + b.val, 0);
  const nbValides      = statut_profs.find(s => s.label === 'Validés')?.val || 0;
  const tauxValid      = totalStatut > 0 ? Math.round((nbValides / totalStatut) * 100) : 0;

  // Boutons onglets domaines
  const domainTabs = (
    <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap', alignItems: 'center' }}>
      {matieres_par_domaine.map((d, i) => (
        <button key={i} onClick={() => setDomainIdx(i)}
          style={{
            padding: '3px 11px', fontSize: '.68rem', fontWeight: 600,
            borderRadius: 20, border: 'none', cursor: 'pointer',
            background: i === domainIdx ? '#6c63ff' : 'var(--surface2)',
            color:      i === domainIdx ? '#fff'    : 'var(--text2)',
            transition: 'all .15s',
          }}
        >
          {d.domaine}
        </button>
      ))}
      {/* Toggle métrique */}
      {domaineActif && (
        <div style={{ display: 'flex', gap: 3, marginLeft: 4 }}>
          {[['nb_resa', '📅 Résa'], ['nb_profs', '👨‍🏫 Profs']].map(([k, l]) => (
            <button key={k} onClick={() => setMetric(k)}
              style={{
                padding: '3px 9px', fontSize: '.65rem', fontWeight: 600,
                borderRadius: 20, border: 'none', cursor: 'pointer',
                background: metric === k ? '#ff6584' : 'var(--surface2)',
                color:      metric === k ? '#fff'    : 'var(--text2)',
                transition: 'all .15s',
              }}
            >
              {l}
            </button>
          ))}
        </div>
      )}
    </div>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

      {/* Titre section */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <div style={{ width: 4, height: 24, background: 'linear-gradient(180deg,#6c63ff,#ff6584)', borderRadius: 2 }} />
        <div>
          <h2 style={{ fontFamily: 'Syne,sans-serif', fontWeight: 800, fontSize: '1.05rem', margin: 0, color: 'var(--text)' }}>
            Statistiques & Analyses
          </h2>
          <p style={{ fontSize: '.72rem', color: 'var(--text2)', margin: 0 }}>
            Données en temps réel — base de données EduMatch
          </p>
        </div>
      </div>

      {/* ── LIGNE 1 ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>

        {/* Graphique 1 — Réservations par mois */}
        <Card
          icon="📈"
          title="Réservations par mois"
          subtitle={totalResa > 0
            ? `✅ Données réelles — ${totalResa} réservation${totalResa > 1 ? 's' : ''} au total`
            : '⚠️ Aucune réservation enregistrée'}
          height={240}
        >
          {reservations_par_mois.length > 0
            ? <LineReservations data={reservations_par_mois} />
            : <Empty msg="Aucune réservation" />}
        </Card>

        {/* Graphique 2 — Matières par domaine */}
        <Card
          icon="📚"
          title="Matières les plus demandées"
          subtitle={domaineActif
            ? `✅ ${domaineActif.domaine} — ${domaineActif.matieres.length} matière${domaineActif.matieres.length > 1 ? 's' : ''}`
            : '⚠️ Aucun domaine configuré dans le référentiel'}
          height={240}
          extra={matieres_par_domaine.length > 0 ? domainTabs : null}
        >
          {domaineActif && domaineActif.matieres.length > 0
            ? <BarMatieres matieres={domaineActif.matieres} metric={metric} />
            : <Empty msg="Aucune matière dans ce domaine" />}
        </Card>
      </div>

      {/* ── LIGNE 2 ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16 }}>

        {/* Graphique 3 — Mode enseignement */}
        <Card
          icon="🌐"
          title="Mode d'enseignement"
          subtitle={modesFiltered.length > 0
            ? `✅ ${modesFiltered.reduce((a, b) => a + b.val, 0)} formateur${modesFiltered.reduce((a, b) => a + b.val, 0) > 1 ? 's' : ''} validés`
            : '⚠️ Aucun formateur validé'}
          height={210}
        >
          {modesFiltered.length > 0
            ? <DonutModes data={modesFiltered} />
            : <Empty msg="Aucun formateur validé" />}
        </Card>

        {/* Graphique 4 — Statut des profs */}
        <Card
          icon="👨‍🏫"
          title="Statut des formateurs"
          subtitle={totalStatut > 0
            ? `✅ Données réelles — ${totalStatut} profil${totalStatut > 1 ? 's' : ''} total`
            : '⚠️ Aucun profil enregistré'}
          height={210}
        >
          {statutFiltered.length > 0
            ? <DonutStatut data={statutFiltered} />
            : <Empty msg="Aucun profil enregistré" />}
        </Card>

        {/* KPIs */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {[
            { icon: '🏆', label: 'Taux de validation',    val: `${tauxValid}%`,                                     color: '#43e97b' },
            { icon: '📅', label: 'Réservations ce mois',  val: stats.reservations_mois ?? reservations_par_mois[5]?.total ?? 0, color: '#6c63ff' },
            { icon: '⏳', label: 'Profils en attente',     val: stats.en_attente ?? statut_profs.find(s => s.label === 'En attente')?.val ?? 0, color: '#f59e0b' },
            { icon: '📋', label: 'Demandes matières',      val: stats.demandes_matieres_pending ?? 0,                color: '#38bdf8' },
          ].map((kpi, i) => (
            <div key={i} style={{
              background: 'var(--surface)', border: '1px solid var(--border)',
              borderRadius: 13, padding: '11px 15px',
              display: 'flex', alignItems: 'center', gap: 12, flex: 1,
            }}>
              <div style={{ width: 36, height: 36, borderRadius: 10, background: kpi.color + '20', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem', flexShrink: 0 }}>
                {kpi.icon}
              </div>
              <div>
                <div style={{ fontFamily: 'Syne,sans-serif', fontWeight: 800, fontSize: '1.2rem', color: kpi.color, lineHeight: 1 }}>
                  {kpi.val}
                </div>
                <div style={{ fontSize: '.68rem', color: 'var(--text2)', marginTop: 3 }}>
                  {kpi.label}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
